const http = require('http');
const assert = require('assert');
const axios = require('./lib/axios');

const data = Array(2 * 10 * 1024 * 1024).join('ж');

const server = http.createServer(function (req, res) {
  res.setHeader('Content-Type', 'text/html; charset=UTF-8');
  res.end();
}).listen(4444, async function () {
  const url = 'http://localhost:4444/';

  await axios.post(url, { data: data }).then(() => console.log('default: OK'));
  await axios.post(url, { data: data }, { maxBodyLength: -1 }).then(() => console.log('maxBodyLength: -1: OK'));
  await axios.post(url, { data: data }, { maxRedirects: 0 }).then(() => console.log('maxRedirects: 0: OK'));
  await axios.post(url, { data: data }, { maxBodyLength: Infinity }).then(() => console.log('maxBodyLength: Infinity: OK'));

  await axios.post(url, { data: data }, { maxBodyLength: 2000 }).then(() => {
    console.log('maxBodyLength: 2000: UNEXPECTED SUCCESS');
    process.exit(1);
  }).catch((err) => {
    assert.equal(err.message, 'Request body larger than maxBodyLength limit');
